class OtherDua {
  final int id;
  final String arabicOnly;
  final String transliteration;
  final String translation;
  final String commonName;
  final String notes;
  final String repetition;
  final String source;

  const OtherDua({
    required this.id,
    required this.arabicOnly,
    required this.transliteration,
    required this.translation,
    required this.commonName,
    required this.notes,
    required this.repetition,
    required this.source,
  });

  String get arabic => arabicOnly;

  /// A few imported Hisnul Muslim entries have no Latin rendering. Keep the
  /// Arabic source untouched and provide a consistent study pronunciation.
  String get displayTransliteration =>
      transliteration.trim().isNotEmpty
          ? transliteration
          : arabicToTransliteration(arabicOnly);
}

String arabicToTransliteration(String value) {
  final result = StringBuffer();
  var previousWasSpace = false;
  for (final rune in value.runes) {
    final char = String.fromCharCode(rune);
    final mapped = switch (char) {
      'ا' || 'أ' || 'إ' || 'ٱ' => 'a',
      'آ' => 'aa',
      'ب' => 'b',
      'ت' => 't',
      'ث' => 'th',
      'ج' => 'j',
      'ح' => 'h',
      'خ' => 'kh',
      'د' => 'd',
      'ذ' => 'dh',
      'ر' => 'r',
      'ز' => 'z',
      'س' => 's',
      'ش' => 'sh',
      'ص' => 's',
      'ض' => 'd',
      'ط' => 't',
      'ظ' => 'dh',
      'ع' => "'",
      'غ' => 'gh',
      'ف' => 'f',
      'ق' => 'q',
      'ك' => 'k',
      'ل' => 'l',
      'م' => 'm',
      'ن' => 'n',
      'ه' => 'h',
      'و' => 'w',
      'ي' || 'ى' => 'y',
      'ء' || 'ئ' || 'ؤ' => "'",
      'ة' => 'ah',
      'َ' || 'ٰ' => 'a',
      'ُ' => 'u',
      'ِ' => 'i',
      'ً' => 'an',
      'ٌ' => 'un',
      'ٍ' => 'in',
      'ّ' || 'ْ' || 'ـ' => '',
      '۝' || '﴿' || '﴾' || '﷽' || 'ﷺ' => '',
      _ => char,
    };
    if (mapped == ' ') {
      if (!previousWasSpace) result.write(' ');
      previousWasSpace = true;
    } else if (mapped.isNotEmpty) {
      result.write(mapped);
      previousWasSpace = false;
    }
  }
  return result.toString().replaceAll(RegExp(r'\s+'), ' ').trim();
}

