    OtherDua(
      id: 15,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0641\u0650\u064a \u0642\u064e\u0644\u0652\u0628\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0641\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0641\u0650\u064a \u0633\u064e\u0645\u0652\u0639\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0641\u0650\u064a \u0628\u064e\u0635\u064e\u0631\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u064e\u0627\u0645\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b \u0648\u064e\u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0639\u0652\u0637\u0650\u0646\u0650\u064a \u0646\u064f\u0648\u0652\u0631\u0627\u064b.",
      transliteration: "",
      translation: "O Allaah, place within my heart light, and upon my tongue light, and within my ears light, and within my eyes light, and place behind me light and in front of me light and above me light and beneath me light. O Allaah, bestow upon me light.",
      commonName: "Supplication when going to the mosque",
      notes: "",
      repetition: "Once, when going to the mosque",
      source: "Hisnul Muslim, Section 12, Item 19",
    ),
    OtherDua(
      id: 16,
      arabicOnly: "\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650 \u0648\u064e\u0628\u0650\u0648\u064e\u062c\u0652\u0647\u0650\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u0650 \u0648\u064e\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u062f\u0650\u064a\u0645\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0627\u0644\u0631\u064e\u0651\u062c\u0650\u064a\u0645\u0650\u060c [\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u064e\u0629\u064f] [\u0648\u064e\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f \u0639\u064e\u0644\u064e\u0649 \u0631\u064e\u0633\u064f\u0648\u0652\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650]\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0641\u0652\u062a\u064e\u062d\u0652 \u0644\u0650\u064a \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e.",
      transliteration: "",
      translation: "I take refuge with Allaah, The Supreme, and with His Noble Face, and His eternal authority from the accursed devil. In the name of Allaah, and prayers and peace be upon the Messenger of Allaah. O Allaah, open the gates of Your mercy for me.",
      commonName: "Supplication upon entering the mosque",
      notes: "",
      repetition: "Once, upon entering the mosque",
      source: "Hisnul Muslim, Section 13, Item 20",
    ),
    OtherDua(
      id: 17,
      arabicOnly: "\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f \u0639\u064e\u0644\u064e\u0649 \u0631\u064e\u0633\u064f\u0648\u0652\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0643\u064e\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0639\u0652\u0635\u0650\u0645\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0627\u0644\u0631\u064e\u0651\u062c\u0650\u064a\u0645\u0650.",
      transliteration: "",
      translation: "In the name of Allaah, and prayers and peace be upon the Messenger of Allaah. O Allaah, I ask You from Your favour. O Allaah, guard me from the accursed devil.",
      commonName: "Supplication upon leaving the mosque",
      notes: "",
      repetition: "Once, upon leaving the mosque",
      source: "Hisnul Muslim, Section 14, Item 21",
    ),
    OtherDua(
      id: 18,
      arabicOnly: "\u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e\u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u0627\u064b \u0639\u064e\u0628\u0652\u062f\u064f\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u060c \u0631\u064e\u0636\u0650\u064a\u062a\u064f \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0631\u064e\u0628\u064e\u0651\u0627\u064b\u060c \u0648\u064e\u0628\u0650\u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0631\u064e\u0633\u064f\u0648\u0644\u0627\u064b \u0648\u064e\u0628\u0650\u0627\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u064e\u0645\u0650 \u062f\u0650\u064a\u0646\u0627\u064b.",
      transliteration: "",
      translation: "And I too bear witness that none has the right to be worshipped except Allaah, alone, without partner, and that Muhammad is His slave and Messenger. I am pleased with Allaah as a Lord, and Muhammad as a Messenger and Islaam as a religion.",
      commonName: "Supplication after the Aadhaan (1) - after the declaration of faith",
      notes: "Said immediately following the declaration of faith called by the muadhdhin.",
      repetition: "Once, after the Aadhaan",
      source: "Hisnul Muslim, Section 15, Item 23",
    ),
    OtherDua(
      id: 19,
      arabicOnly: "",
      transliteration: "",
      translation: "One should then send prayers on the Prophet (peace be upon him) after answering the call of the muadhdhin.",
      commonName: "Instruction: sending prayers on the Prophet after the Aadhaan",
      notes: "Instructional note, not a spoken text.",
      repetition: "",
      source: "Hisnul Muslim, Section 15, Item 24",
    ),
    OtherDua(
      id: 20,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0631\u064e\u0628\u064e\u0651 \u0647\u064e\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u062a\u064e\u0651\u0627\u0645\u064e\u0651\u0629\u0650 \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u0650 \u0622\u062a\u0650 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u0627\u064b \u0627\u0644\u0652\u0648\u064e\u0633\u0650\u064a\u0644\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0636\u0650\u064a\u0644\u064e\u0629\u064e \u0648\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u0652\u0647\u064f \u0645\u064e\u0642\u064e\u0627\u0645\u0627\u064b \u0645\u064e\u062d\u0652\u0645\u064f\u0648\u062f\u0627\u064b \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u0652\u062a\u064e\u0647\u064f\u060c \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u0644\u0627\u064e \u062a\u064f\u062e\u0652\u0644\u0650\u0641\u064f \u0627\u0644\u0652\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e.",
      transliteration: "",
      translation: "O Allaah, Owner of this perfect call and Owner of this prayer to be performed, bestow upon Muhammad al-waseelah and al-fadeelah and send him upon a praised platform which You have promised him. Verily, You never fail in Your promise.",
      commonName: "Supplication after the Aadhaan (2)",
      notes: "Al-waseelah is a station in Paradise; al-fadeelah is a rank above the rest of creation.",
      repetition: "Once, after the Aadhaan",
      source: "Hisnul Muslim, Section 15, Item 25",
    ),
    OtherDua(
      id: 21,
      arabicOnly: "",
      transliteration: "",
      translation: "One should also supplicate for himself during the time between the aadhaan and the iqaamah as supplication at such time is not rejected.",
      commonName: "Instruction: supplicating between the Aadhaan and Iqaamah",
      notes: "Instructional note, not a spoken text.",
      repetition: "",
      source: "Hisnul Muslim, Section 15, Item 26",
    ),
    OtherDua(
      id: 22,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u064e\u0627\u0639\u0650\u062f\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u064a\u064e \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0627\u0639\u064e\u062f\u0652\u062a\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u0650\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0646\u064e\u0642\u0650\u0651\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u064a\u064e \u0643\u064e\u0645\u064e\u0627 \u064a\u064f\u0646\u064e\u0642\u064e\u0651\u0649 \u0627\u0644\u062b\u064e\u0651\u0648\u0652\u0628\u064f \u0627\u0644\u0623\u064e\u0628\u0652\u064a\u064e\u0636\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u064e\u0651\u0646\u064e\u0633\u0650\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0633\u0650\u0644\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u064a\u064e \u0628\u0650\u0627\u0644\u062b\u064e\u0651\u0644\u0652\u062c\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0631\u064e\u062f\u0650.",
      transliteration: "",
      translation: "O Allaah, distance me from my sins just as You have distanced The East from The West, O Allaah, purify me of my sins as a white robe is purified of filth, O Allaah, cleanse me of my sins with snow, water, and ice.",
      commonName: "Supplication at the start of the prayer (after takbeer) - 1",
      notes: "",
      repetition: "Once, after opening takbeer",
      source: "Hisnul Muslim, Section 16, Item 27",
    ),
    OtherDua(
      id: 23,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0633\u0652\u0645\u064f\u0643\u064e \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u062c\u064e\u062f\u064f\u0651\u0643\u064e \u0648\u064e\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u063a\u064e\u064a\u0652\u0631\u064f\u0643\u064e.",
      transliteration: "",
      translation: "How perfect You are O Allaah, and I praise You. Blessed be Your name, and lofty is Your position and none has the right to be worshipped except You.",
      commonName: "Supplication at the start of the prayer (after takbeer) - 2",
      notes: "",
      repetition: "Once, after opening takbeer",
      source: "Hisnul Muslim, Section 16, Item 28",
    ),
    OtherDua(
      id: 24,
      arabicOnly: "\u0648\u064e\u062c\u064e\u0651\u0647\u0652\u062a\u064f \u0648\u064e\u062c\u0652\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u064e\u0651\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0627\u064b \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e\u060c \u0625\u0650\u0646\u064e\u0651 \u0635\u064e\u0644\u0627\u064e\u062a\u0650\u064a \u0648\u064e\u0646\u064f\u0633\u064f\u0643\u0650\u064a \u0648\u064e\u0645\u064e\u062d\u0652\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u0650\u064a \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e\u060c \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0628\u0650\u0630\u064e\u0644\u0650\u0643\u064e \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e. \u0623\u064e\u0646\u0652\u062a\u064e \u0631\u064e\u0628\u0650\u0651\u064a \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e\u060c \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0648\u064e\u0627\u0639\u0652\u062a\u064e\u0631\u064e\u0641\u0652\u062a\u064f \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u064a \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u064a \u062c\u064e\u0645\u0650\u064a\u0639\u0627\u064b \u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0644\u0627\u064e \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u064f\u0651\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e. \u0648\u064e\u0627\u0647\u0652\u062f\u0650\u0646\u0650\u064a \u0644\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650 \u0627\u0644\u0623\u064e\u062e\u0652\u0644\u0627\u064e\u0642\u0650 \u0644\u0627\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0644\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650\u0647\u064e\u0627 \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e\u060c \u0648\u064e\u0627\u0635\u0652\u0631\u0650\u0641\u0652 \u0639\u064e\u0646\u0650\u0651\u064a \u0633\u064e\u064a\u0650\u0651\u0626\u064e\u0647\u064e\u0627\u060c \u0644\u0627\u064e \u064a\u064e\u0635\u0652\u0631\u0650\u0641\u064f \u0639\u064e\u0646\u0650\u0651\u064a \u0633\u064e\u064a\u0650\u0651\u0626\u064e\u0647\u064e\u0627 \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e\u060c \u0644\u064e\u0628\u064e\u0651\u064a\u0652\u0643\u064e \u0648\u064e\u0633\u064e\u0639\u0652\u062f\u064e\u064a\u0652\u0643\u064e\u060c \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064f \u0643\u064f\u0644\u064f\u0651\u0647\u064f \u0628\u0650\u064a\u064e\u062f\u064e\u064a\u0652\u0643\u064e\u060c \u0648\u064e\u0627\u0644\u0634\u064e\u0651\u0631\u064f\u0651 \u0644\u064e\u064a\u0652\u0633\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e. \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u064a\u0652\u062a\u064e \u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0643\u064e \u0648\u064e\u0623\u064e\u062a\u064f\u0648\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e.",
      transliteration: "",
      translation: "I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allaah). Indeed my prayer, my sacrifice, my life and my death are for Allaah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allaah, You are the Sovereign, none has the right to be worshipped except You. You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You. Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You. Here I am, in answer to Your call, happy to serve you. All good is within Your hands and evil does not stem from You. I exist by your will and will return to you. Blessed and High are You, I seek Your forgiveness and repent unto You.",
      commonName: "Supplication at the start of the prayer (after takbeer) - 3",
      notes: "Allaah does not create pure evil which does not have any good, benefit, or wisdom, nor does He punish anyone without a sin having been committed.",
      repetition: "Once, after opening takbeer",
      source: "Hisnul Muslim, Section 16, Item 29",
    ),
    OtherDua(
      id: 25,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0631\u064e\u0628\u064e\u0651 \u062c\u0650\u0628\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e\u060c \u0648\u064e\u0645\u0650\u064a\u0643\u064e\u0627\u0626\u0650\u064a\u0644\u064e\u060c \u0648\u064e\u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0641\u0650\u064a\u0644\u064e\u060c \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650\u060c \u0639\u064e\u0627\u0644\u0650\u0645\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u064e\u0651\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e. \u0627\u0647\u0652\u062f\u0650\u0646\u0650\u064a \u0644\u0650\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064f\u0644\u0650\u0641\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0650\u0651 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0643\u064e \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d.",
      transliteration: "",
      translation: "O Allaah, Lord of Jibraa'eel, Meekaa'eel and Israafeel (great angels), Creator of the heavens and the Earth, Knower of the seen and the unseen. You are the arbitrator between Your servants in that which they have disputed. Guide me to the truth by Your leave, in that which they have differed, for verily You guide whom You will to a straight path.",
      commonName: "Supplication at the start of the prayer (after takbeer) - 4",
      notes: "",
      repetition: "Once, after opening takbeer",
      source: "Hisnul Muslim, Section 16, Item 30",
    ),
    OtherDua(
      id: 26,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0643\u064e\u0628\u0650\u064a\u0631\u0627\u064b\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0643\u064e\u0628\u0650\u064a\u0631\u0627\u064b\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0643\u064e\u0628\u0650\u064a\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u0627\u064b\u060c \u0648\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u0627\u064b. (\u062b\u0644\u0627\u062b\u0627\u064b) \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u062e\u0650\u0647\u0650 \u0648\u064e\u0646\u064e\u0641\u0652\u062b\u0650\u0647\u0650 \u0648\u064e\u0647\u064e\u0645\u0652\u0632\u0650\u0647\u0650.",
      transliteration: "",
      translation: "Allaah is Most Great, Allaah is Most Great, Allaah is Most Great, much praise is for Allaah, much praise is for Allaah, much praise is for Allaah, and I declare the perfection of Allaah in the early morning and in the late afternoon. (three times) I take refuge with Allaah from the devil, from his pride, his poetry and his madness.",
      commonName: "Supplication at the start of the prayer (after takbeer) - 5",
      notes: "",
      repetition: "Three times, after opening takbeer",
      source: "Hisnul Muslim, Section 16, Item 31",
    ),
    OtherDua(
      id: 27,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0623\u064e\u0646\u0652\u062a\u064e \u0646\u064f\u0648\u0631\u064f \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u064e\u0651\u060c \u0648\u064e\u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0623\u064e\u0646\u0652\u062a\u064e \u0642\u064e\u064a\u0650\u0651\u0645\u064f \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u064e\u0651\u060c [\u0648\u064e\u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0623\u064e\u0646\u0652\u062a\u064e \u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u064e\u0651] [\u0648\u064e\u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u064e\u0643\u064e \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u064e\u0651] [\u0648\u064e\u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650] [\u0648\u064e\u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f] \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u064f\u0651\u060c \u0648\u064e\u0648\u064e\u0639\u0652\u062f\u064f\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u064f\u0651\u060c \u0648\u064e\u0642\u064e\u0648\u0652\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u064f\u0651\u060c \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0624\u064f\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u064f\u0651\u060c \u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064f \u062d\u064e\u0642\u064c\u0651\u060c \u0648\u064e\u0627\u0644\u0646\u064e\u0651\u0627\u0631\u064f \u062d\u064e\u0642\u064c\u0651\u060c \u0648\u064e\u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u064f\u0651\u0648\u0646\u064e \u062d\u064e\u0642\u064c\u0651\u060c \u0648\u064e\u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064c \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u062d\u064e\u0642\u064c\u0651\u060c \u0648\u064e\u0627\u0644\u0633\u064e\u0651\u0627\u0639\u064e\u0629\u064f \u062d\u064e\u0642\u064c\u0651. [\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u064e\u0643\u064e \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u062a\u064f\u060c \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u062a\u064e\u0648\u064e\u0643\u064e\u0651\u0644\u0652\u062a\u064f\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u060c \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0646\u064e\u0628\u0652\u062a\u064f\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u062e\u064e\u0627\u0635\u064e\u0645\u0652\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062d\u064e\u0627\u0643\u064e\u0645\u0652\u062a\u064f. \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0651\u0645\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062e\u064e\u0651\u0631\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0631\u064e\u0631\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0646\u0652\u062a\u064f] [\u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u062f\u0650\u0651\u0645\u064f\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u064e\u062e\u0650\u0651\u0631\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e] [\u0623\u064e\u0646\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u0647\u0650\u064a \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e].",
      transliteration: "",
      translation: "O Allaah, to You belongs all praise, You are the Light of the heavens and the Earth and all that is within them. To You belongs all praise, You are the Sustainer of the heavens and the Earth and all that is within them... [continues through the full supplication ending] None has the right to be worshipped except You, You are my Deity, none has the right to be worshipped except You.",
      commonName: "Opening supplication when rising from sleep to pray at night (Tahajjud)",
      notes: "Al-Muqaddim and Al-Mu'akhkhir: Allaah puts forward and favours whom He wills from His creation, and defers and holds back whom He wills, in accordance with His wisdom.",
      repetition: "Once, as an opening supplication for night prayer",
      source: "Hisnul Muslim, Section 16, Item 32",
    ),
    OtherDua(
      id: 28,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650. (\u062b\u0644\u0627\u062b\u0627\u064b)",
      transliteration: "",
      translation: "How perfect my Lord is, The Supreme.",
      commonName: "Supplication while bowing in prayer (rukoo')",
      notes: "",
      repetition: "Three times, while bowing (rukoo')",
      source: "Hisnul Muslim, Section 17, Item 33",
    ),
    OtherDua(
      id: 29,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0630\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0628\u064e\u0631\u064f\u0648\u062a\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u0628\u0652\u0631\u0650\u064a\u064e\u0627\u0621\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0638\u064e\u0645\u064e\u0629\u0650.",
      transliteration: "",
      translation: "How perfect He is, The Possessor of total power, sovereignty, magnificence and grandeur.",
      commonName: "Supplication while bowing in prayer (rukoo') - variant",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 17, Item 37",
    ),
    OtherDua(
      id: 30,
      arabicOnly: "\u0633\u064e\u0645\u0650\u0639\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u062d\u064e\u0645\u0650\u062f\u064e\u0647\u064f.",
      transliteration: "",
      translation: "May Allaah answer he who praises Him.",
      commonName: "Supplication upon rising from bowing (1)",
      notes: "This supplication is to be made while rising.",
      repetition: "Once, while rising from rukoo'",
      source: "Hisnul Muslim, Section 18, Item 38",
    ),
    OtherDua(
      id: 31,
      arabicOnly: "\u0631\u064e\u0628\u064e\u0651\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u062d\u064e\u0645\u0652\u062f\u0627\u064b \u0643\u064e\u062b\u0650\u064a\u0631\u0627\u064b \u0637\u064e\u064a\u0650\u0651\u0628\u0627\u064b \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u0627\u064b \u0641\u0650\u064a\u0647\u0650.",
      transliteration: "",
      translation: "Our Lord, for You is all praise, an abundant beautiful blessed praise.",
      commonName: "Supplication upon rising from bowing (2)",
      notes: "",
      repetition: "Once, after standing from rukoo'",
      source: "Hisnul Muslim, Section 18, Item 39",
    ),
    OtherDua(
      id: 32,
      arabicOnly: "\u0645\u0650\u0644\u0652\u0621\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u0650\u0644\u0652\u0621\u064e \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0645\u0650\u0644\u0652\u0621\u064e \u0645\u064e\u0627 \u0634\u0650\u0626\u0652\u062a\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0628\u064e\u0639\u0652\u062f\u064f. \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u062b\u064e\u0651\u0646\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u062c\u0652\u062f\u0650 \u0623\u064e\u062d\u064e\u0642\u064f\u0651 \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u064f \u0648\u064e\u0643\u064f\u0644\u064f\u0651\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0639\u064e\u0628\u0652\u062f\u064c. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u0627\u064e \u0645\u064e\u0627\u0646\u0650\u0639\u064e \u0644\u0650\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0637\u064e\u064a\u0652\u062a\u064e \u0648\u064e\u0644\u0627\u064e \u0645\u064f\u0639\u0652\u0637\u0650\u064a\u064e \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u0652\u062a\u064e \u0648\u064e\u0644\u0627\u064e \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u062f\u0650\u0651 \u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u062f\u064f\u0651.",
      transliteration: "",
      translation: "The heavens and the Earth and all between them abound with Your praises, and all that You will abounds with Your praises. O Possessor of praise and majesty, the truest thing a slave has said (of You) and we are all Your slaves. O Allaah, none can prevent what You have willed to bestow and none can bestow what You have willed to prevent, and no wealth or majesty can benefit anyone, as from You is all wealth and majesty.",
      commonName: "Supplication upon rising from bowing (3)",
      notes: "This supplication is made optionally only in conjunction with the previous one.",
      repetition: "Once, after standing from rukoo'",
      source: "Hisnul Muslim, Section 18, Item 40",
    ),
    OtherDua(
      id: 33,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0623\u064e\u0639\u0652\u0644\u064e\u0649. (\u062b\u0644\u0627\u062b\u0627\u064b)",
      transliteration: "",
      translation: "How Perfect my Lord is, The Most High.",
      commonName: "Supplication whilst prostrating (sujuud) - 1",
      notes: "",
      repetition: "Three times, while prostrating",
      source: "Hisnul Muslim, Section 19, Item 41",
    ),
    OtherDua(
      id: 34,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0631\u064e\u0628\u064e\u0651\u0646\u064e\u0627 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a.",
      transliteration: "",
      translation: "How perfect You are O Allaah, our Lord, and I praise You. O Allaah, forgive me.",
      commonName: "Supplication whilst prostrating (sujuud) - 2",
      notes: "",
      repetition: "While prostrating",
      source: "Hisnul Muslim, Section 19, Item 42",
    ),
    OtherDua(
      id: 35,
      arabicOnly: "\u0633\u064f\u0628\u064f\u0651\u0648\u062d\u064c \u0642\u064f\u062f\u064f\u0651\u0648\u0633\u064c \u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0652\u0645\u064e\u0644\u0627\u064e\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0631\u064f\u0651\u0648\u062d\u0650.",
      transliteration: "",
      translation: "Perfect and Holy (He is), Lord of the angels and the Ruuh (i.e. Jibraa'eel).",
      commonName: "Supplication whilst prostrating (sujuud) - 3",
      notes: "",
      repetition: "While prostrating",
      source: "Hisnul Muslim, Section 19, Item 43",
    ),
    OtherDua(
      id: 36,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u064e\u0643\u064e \u0633\u064e\u062c\u064e\u062f\u0652\u062a\u064f \u0648\u064e\u0628\u0650\u0643\u064e \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u060c \u0648\u064e\u0644\u064e\u0643\u064e \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u062a\u064f \u0633\u064e\u062c\u064e\u062f\u064e \u0648\u064e\u062c\u0652\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u064e\u0651\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f \u0648\u064e\u0635\u064e\u0648\u064e\u0651\u0631\u064e\u0647\u064f \u0648\u064e\u0634\u064e\u0642\u064e\u0651 \u0633\u064e\u0645\u0652\u0639\u064e\u0647\u064f \u0648\u064e\u0628\u064e\u0635\u064e\u0631\u064e\u0647\u064f \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u0650\u064a\u0646\u064e.",
      transliteration: "",
      translation: "O Allaah, unto You I have prostrated and in You I have believed, and unto You I have submitted. My face has prostrated before He Who created it and fashioned it, and brought forth its faculties of hearing and seeing. Blessed is Allaah, the Best of creators.",
      commonName: "Supplication whilst prostrating (sujuud) - 4",
      notes: "",
      repetition: "While prostrating",
      source: "Hisnul Muslim, Section 19, Item 44",
    ),
    OtherDua(
      id: 37,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0630\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0628\u064e\u0631\u064f\u0648\u062a\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u0628\u0652\u0631\u0650\u064a\u064e\u0627\u0621\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0638\u064e\u0645\u064e\u0629\u0650.",
      transliteration: "",
      translation: "How perfect He is, The Possessor of total power, sovereignty, magnificence and grandeur.",
      commonName: "Supplication whilst prostrating (sujuud) - 5",
      notes: "",
      repetition: "While prostrating",
      source: "Hisnul Muslim, Section 19, Item 45",
