    OtherDua(
      id: 38,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0630\u064e\u0646\u0652\u0628\u0650\u064a \u0643\u064f\u0644\u064e\u0651\u0647\u064f\u060c \u062f\u0650\u0642\u064e\u0651\u0647\u064f \u0648\u064e\u062c\u0650\u0644\u064e\u0651\u0647\u064f\u060c \u0648\u064e\u0623\u064e\u0648\u064e\u0651\u0644\u064e\u0647\u064f \u0648\u064e\u0622\u062e\u0650\u0631\u064e\u0647\u064f \u0648\u064e\u0639\u064e\u0644\u0627\u064e\u0646\u0650\u064a\u064e\u062a\u064e\u0647\u064f \u0648\u064e\u0633\u0650\u0631\u064e\u0651\u0647\u064f.",
      transliteration: "",
      translation: "O Allaah, forgive me all of my sins, the small and great of them, the first and last of them, and the seen and hidden of them.",
      commonName: "Supplication whilst prostrating (sujuud) - 6",
      notes: "",
      repetition: "While prostrating",
      source: "Hisnul Muslim, Section 19, Item 46",
    ),
    OtherDua(
      id: 39,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u0650\u0636\u064e\u0627\u0643\u064e \u0645\u0650\u0646\u0652 \u0633\u064e\u062e\u064e\u0637\u0650\u0643\u064e\u060c \u0648\u064e\u0628\u0650\u0645\u064f\u0639\u064e\u0627\u0641\u064e\u0627\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064f\u0642\u064f\u0648\u0628\u064e\u062a\u0650\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652\u0643\u064e\u060c \u0644\u0627\u064e \u0623\u064f\u062d\u0652\u0635\u0650\u064a \u062b\u064e\u0646\u064e\u0627\u0621\u064b \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062b\u0652\u0646\u064e\u064a\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e.",
      transliteration: "",
      translation: "O Allaah, I take refuge within Your pleasure from Your displeasure and within Your pardon from Your punishment, and I take refuge in You from You. I cannot enumerate Your praise. You are as You have praised Yourself.",
      commonName: "Supplication whilst prostrating (sujuud) - 7",
      notes: "",
      repetition: "While prostrating",
      source: "Hisnul Muslim, Section 19, Item 47",
    ),
    OtherDua(
      id: 40,
      arabicOnly: "\u0631\u064e\u0628\u0650\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a\u060c \u0631\u064e\u0628\u0650\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a.",
      transliteration: "",
      translation: "My Lord forgive me, My Lord forgive me.",
      commonName: "Supplication between the two prostrations (1)",
      notes: "",
      repetition: "Between the two prostrations",
      source: "Hisnul Muslim, Section 20, Item 48",
    ),
    OtherDua(
      id: 41,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a\u060c \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u0650\u064a\u060c \u0648\u064e\u0627\u0647\u0652\u062f\u0650\u0646\u0650\u064a\u060c \u0648\u064e\u0627\u062c\u0652\u0628\u064f\u0631\u0652\u0646\u0650\u064a\u060c \u0648\u064e\u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u060c \u0648\u064e\u0627\u0631\u0652\u0632\u064f\u0642\u0652\u0646\u0650\u064a\u060c \u0648\u064e\u0627\u0631\u0652\u0641\u064e\u0639\u0652\u0646\u0650\u064a.",
      transliteration: "",
      translation: "O Allaah, forgive me, have mercy upon me, guide me, enrich me, give me health, grant me sustenance and raise my rank.",
      commonName: "Supplication between the two prostrations (2)",
      notes: "",
      repetition: "Between the two prostrations",
      source: "Hisnul Muslim, Section 20, Item 49",
    ),
    OtherDua(
      id: 42,
      arabicOnly: "\u0633\u064e\u062c\u064e\u062f\u064e \u0648\u064e\u062c\u0652\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u064e\u0651\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f \u0648\u064e\u0634\u064e\u0642\u064e\u0651 \u0633\u064e\u0645\u0652\u0639\u064e\u0647\u064f \u0648\u064e\u0628\u064e\u0635\u064e\u0631\u064e\u0647\u064f \u0628\u0650\u062d\u064e\u0648\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0642\u064f\u0648\u064e\u0651\u062a\u0650\u0647\u0650. \u0641\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u0650\u064a\u0646\u064e.",
      transliteration: "",
      translation: "My face fell prostrate before He who created it and brought forth its faculties of hearing and seeing by His might and power. So Blessed is Allaah, the best of creators.",
      commonName: "Supplication when prostrating due to recitation of the Qur'aan",
      notes: "",
      repetition: "Once, during prostration of recitation",
      source: "Hisnul Muslim, Section 21, Item 50",
    ),
    OtherDua(
      id: 43,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0643\u0652\u062a\u064f\u0628\u0652 \u0644\u0650\u064a \u0628\u0650\u0647\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e \u0623\u064e\u062c\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0636\u064e\u0639\u0652 \u0639\u064e\u0646\u0650\u0651\u064a \u0628\u0650\u0647\u064e\u0627 \u0648\u0650\u0632\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0647\u064e\u0627 \u0644\u0650\u064a \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e \u0630\u064f\u062e\u0652\u0631\u0627\u064b\u060c \u0648\u064e\u062a\u064e\u0642\u064e\u0628\u064e\u0651\u0644\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0650\u0651\u064a \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0642\u064e\u0628\u064e\u0651\u0644\u0652\u062a\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u0628\u0652\u062f\u0650\u0643\u064e \u062f\u064e\u0627\u0648\u064f\u062f\u064e.",
      transliteration: "",
      translation: "O Allaah, record for me a reward for this (prostration), and remove from me a sin. Save it for me and accept it from me just as You had accepted it from Your servant Daawud.",
      commonName: "Supplication when prostrating due to recitation of the Qur'aan (2)",
      notes: "",
      repetition: "Once, during prostration of recitation",
      source: "Hisnul Muslim, Section 21, Item 51",
    ),
    OtherDua(
      id: 44,
      arabicOnly: "\u0627\u0644\u062a\u064e\u0651\u062d\u0650\u064a\u064e\u0651\u0627\u062a\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0648\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0637\u064e\u0651\u064a\u0650\u0651\u0628\u064e\u0627\u062a\u064f\u060c \u0648\u064e\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u064a\u064f\u0651\u0647\u064e\u0627 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u064f\u0651 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0628\u064e\u0631\u064e\u0643\u064e\u0627\u062a\u064f\u0647\u064f\u060c \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u0635\u064e\u0651\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e. \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u0627\u064b \u0639\u064e\u0628\u0652\u062f\u064f\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f.",
      transliteration: "",
      translation: "At-Tahiyyaat is for Allaah. All acts of worship and good deeds are for Him. Peace and the mercy and blessings of Allaah be upon you O Prophet. Peace be upon us and all of Allaah's righteous servants. I bear witness that none has the right to be worshipped except Allaah and I bear witness that Muhammad is His slave and Messenger.",
      commonName: "The Tashahhud",
      notes: "At-Tahiyyaat means all words which indicate the glorification of Allaah, His eternal existence, His perfection and His sovereignty.",
      repetition: "In the sitting position of prayer",
      source: "Hisnul Muslim, Section 22, Item 52",
    ),
    OtherDua(
      id: 45,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0635\u064e\u0644\u0650\u0651 \u0639\u064e\u0644\u064e\u0649 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0622\u0644\u0650 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0643\u064e\u0645\u064e\u0627 \u0635\u064e\u0644\u064e\u0651\u064a\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u062d\u064e\u0645\u0650\u064a\u062f\u064c \u0645\u064e\u062c\u0650\u064a\u062f\u064c\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u064e\u0627\u0631\u0650\u0643\u0652 \u0639\u064e\u0644\u064e\u0649 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0622\u0644\u0650 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u062d\u064e\u0645\u0650\u064a\u062f\u064c \u0645\u064e\u062c\u0650\u064a\u062f\u064c.",
      transliteration: "",
      translation: "O Allaah, send prayers upon Muhammad and the followers of Muhammad, just as You sent prayers upon Ibraaheem and the followers of Ibraaheem, verily You are full of praise and majesty. O Allaah, send blessings upon Muhammad and the followers of Muhammad, just as You sent blessings upon Ibraaheem and the followers of Ibraaheem, verily You are full of praise and majesty.",
      commonName: "Prayers upon the Prophet after the tashahhud",
      notes: "Sending prayers means to praise and exalt him in the highest and superior of gatherings, that of the closest angels to Allaah.",
      repetition: "In the sitting position of prayer, after the tashahhud",
      source: "Hisnul Muslim, Section 23, Item 53",
    ),
    OtherDua(
      id: 46,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0635\u064e\u0644\u0650\u0651 \u0639\u064e\u0644\u064e\u0649 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650 \u0648\u064e\u0630\u064f\u0631\u0650\u0651\u064a\u064e\u0651\u062a\u0650\u0647\u0650 \u0643\u064e\u0645\u064e\u0627 \u0635\u064e\u0644\u064e\u0651\u064a\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e\u060c \u0648\u064e\u0628\u064e\u0627\u0631\u0650\u0643\u0652 \u0639\u064e\u0644\u064e\u0649 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650 \u0648\u064e\u0630\u064f\u0631\u0650\u0651\u064a\u064e\u0651\u062a\u0650\u0647\u0650 \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e. \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u062d\u064e\u0645\u0650\u064a\u062f\u064c \u0645\u064e\u062c\u0650\u064a\u062f\u064c.",
      transliteration: "",
      translation: "O Allaah, send prayers upon Muhammad and upon the wives and descendants of Muhammad, just as You sent prayers upon the family of Ibraheem, and send blessings upon Muhammad and upon the wives and descendants of Muhammad, just as You sent blessings upon the family of Ibraheem. Verily, You are full of praise and majesty.",
      commonName: "Prayers upon the Prophet after the tashahhud (variant, with wives and descendants)",
      notes: "",
      repetition: "In the sitting position of prayer, after the tashahhud",
      source: "Hisnul Muslim, Section 23, Item 54",
    ),
    OtherDua(
      id: 47,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u062c\u064e\u0647\u064e\u0646\u064e\u0651\u0645\u064e\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u062d\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0645\u064e\u0627\u062a\u0650\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u0650 \u0627\u0644\u062f\u064e\u0651\u062c\u064e\u0651\u0627\u0644\u0650.",
      transliteration: "",
      translation: "O Allaah, I take refuge in You from the punishment of the grave, from the torment of the Fire, from the trials and tribulations of life and death and from the evil affliction of Al-Maseeh Ad-Dajjaal.",
      commonName: "Supplication after the last tashahhud and before salaam (1)",
      notes: "Al-Maseeh Ad-Dajjaal (the False Messiah) is among the great signs of the Last Hour, warned about by every Prophet. He will appear from Asbahaan, Iran, be given special powers, claim prophethood and then divinity, be blind in his right eye, and have 'Kaafir' written between his eyes.",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 55",
    ),
    OtherDua(
      id: 48,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u0650 \u0627\u0644\u062f\u064e\u0651\u062c\u064e\u0651\u0627\u0644\u0650\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u062d\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0645\u064e\u0627\u062a\u0650. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0623\u0652\u062b\u064e\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u064e\u0645\u0650.",
      transliteration: "",
      translation: "O Allaah, I take refuge in You from the punishment of the grave, and I take refuge in You from the temptation and trial of Al-Maseeh Ad-Dajjaal, and I take refuge in You from the trials and tribulations of life and death. O Allaah, I take refuge in You from sin and debt.",
      commonName: "Supplication after the last tashahhud and before salaam (2)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 56",
    ),
    OtherDua(
      id: 49,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0638\u064f\u0644\u0652\u0645\u0627\u064b \u0643\u064e\u062b\u0650\u064a\u0631\u0627\u064b \u0648\u064e\u0644\u0627\u064e \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u064f\u0651\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u0650\u064a\u060c \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u064e\u0651\u062d\u0650\u064a\u0645\u064f.",
      transliteration: "",
      translation: "O Allaah, I have indeed oppressed my soul excessively and none can forgive sin except You, so forgive me a forgiveness from Yourself and have mercy upon me. Surely, You are The Most-Forgiving, The Most-Merciful.",
      commonName: "Supplication after the last tashahhud and before salaam (3)",
      notes: "A forgiveness from Yourself: from Your innermost grace without deserving it, befitting Your tremendous generosity.",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 57",
    ),
    OtherDua(
      id: 50,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0651\u0645\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062e\u064e\u0651\u0631\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0631\u064e\u0631\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0646\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0631\u064e\u0641\u0652\u062a\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0650\u0651\u064a. \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u062f\u0650\u0651\u0645\u064f\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u064e\u062e\u0650\u0651\u0631\u064f \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e.",
      transliteration: "",
      translation: "O Allaah, forgive me for those sins which have come to pass as well as those which shall come to pass, and those I have committed in secret as well as those I have made public, and where I have exceeded all bounds as well as those things about which You are more knowledgeable. You are Al-Muqaddim and Al-Mu'akhkhir. None has the right to be worshipped except You.",
      commonName: "Supplication after the last tashahhud and before salaam (4)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 58",
    ),
    OtherDua(
      id: 51,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0639\u0650\u0646\u0650\u0651\u064a \u0639\u064e\u0644\u064e\u0649 \u0630\u0650\u0643\u0652\u0631\u0650\u0643\u064e\u060c \u0648\u064e\u0634\u064f\u0643\u0652\u0631\u0650\u0643\u064e\u060c \u0648\u064e\u062d\u064f\u0633\u0652\u0646\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0643\u064e.",
      transliteration: "",
      translation: "O Allaah, help me to remember You, to thank You, and to worship You in the best of manners.",
      commonName: "Supplication after the last tashahhud and before salaam (5)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 59",
    ),
    OtherDua(
      id: 52,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064f\u0628\u0652\u0646\u0650\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652 \u0623\u064f\u0631\u064e\u062f\u064e\u0651 \u0625\u0650\u0644\u064e\u0649 \u0623\u064e\u0631\u0652\u0630\u064e\u0644\u0650 \u0627\u0644\u0652\u0639\u064f\u0645\u064f\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650.",
      transliteration: "",
      translation: "O Allaah, I take refuge in You from miserliness and cowardice, I take refuge in You lest I be returned to the worst of lives, and I take refuge in You from the trials and tribulations of this life and the punishment of the grave.",
      commonName: "Supplication after the last tashahhud and before salaam (6)",
      notes: "The worst of lives refers to old age, being weak, incapable and in a state of fear.",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 60",
    ),
    OtherDua(
      id: 53,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064e \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650.",
      transliteration: "",
      translation: "O Allaah, I ask You to grant me Paradise and I take refuge in You from the Fire.",
      commonName: "Supplication after the last tashahhud and before salaam (7)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 61",
    ),
    OtherDua(
      id: 107,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0647\u064f\u060c \u0648\u064e\u0639\u064e\u0627\u0641\u0650\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u060c \u0648\u064e\u0623\u064e\u0643\u0652\u0631\u0650\u0645\u0652 \u0646\u064f\u0632\u064f\u0644\u064e\u0647\u064f \u0648\u064e\u0648\u064e\u0633\u0650\u0651\u0639\u0652 \u0645\u064f\u062f\u0652\u062e\u064e\u0644\u064e\u0647\u064f\u060c \u0648\u064e\u0627\u063a\u0652\u0633\u0650\u0644\u0652\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u062b\u064e\u0651\u0644\u0652\u062c\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0631\u064e\u062f\u0650\u060c \u0648\u064e\u0646\u064e\u0642\u0650\u0651\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0651\u064a\u0652\u062a\u064e \u0627\u0644\u062b\u064e\u0651\u0648\u0652\u0628\u064e \u0627\u0644\u0623\u064e\u0628\u0652\u064a\u064e\u0636\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u064e\u0651\u0646\u064e\u0633\u0650\u060c \u0648\u064e\u0623\u064e\u0628\u0652\u062f\u0650\u0644\u0652\u0647\u064f \u062f\u064e\u0627\u0631\u0627\u064b \u062e\u064e\u064a\u0652\u0631\u0627\u064b \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0631\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0627\u064b \u062e\u064e\u064a\u0652\u0631\u0627\u064b \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0632\u064e\u0648\u0652\u062c\u0627\u064b \u062e\u064e\u064a\u0652\u0631\u0627\u064b \u0645\u0650\u0646\u0652 \u0632\u064e\u0648\u0652\u062c\u0650\u0647\u0650\u060c \u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064e\u060c \u0648\u064e\u0623\u064e\u0639\u0650\u0630\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650.",
      transliteration: "",
      translation: "O Allaah, forgive and have mercy upon him, excuse him and pardon him, and make honourable his reception. Expand his entry, and cleanse him with water, snow, and ice, and purify him of sin as a white robe is purified of filth. Exchange his home for a better home, and his family for a better family, and his spouse for a better spouse. Admit him into the Garden, protect him from the punishment of the grave and the torment of the Fire.",
      commonName: "Supplication for the deceased at the funeral prayer (1)",
      notes: "",
      repetition: "At the funeral prayer",
      source: "Hisnul Muslim, Section 51, Item 148",
    ),
    OtherDua(
      id: 108,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u062d\u064e\u064a\u0650\u0651\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u064a\u0650\u0651\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0634\u064e\u0627\u0647\u0650\u062f\u0650\u0646\u064e\u0627 \u0648\u064e\u063a\u064e\u0627\u0626\u0650\u0628\u0650\u0646\u064e\u0627\u060c \u0648\u064e\u0635\u064e\u063a\u0650\u064a\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u0650\u0646\u064e\u0627\u060c \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064f\u0646\u0652\u062b\u064e\u0627\u0646\u064e\u0627. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u064a\u064e\u064a\u0652\u062a\u064e\u0647\u064f \u0645\u0650\u0646\u064e\u0651\u0627 \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u064e\u0645\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0641\u064e\u0651\u064a\u0652\u062a\u064e\u0647\u064f \u0645\u0650\u0646\u064e\u0651\u0627 \u0641\u064e\u062a\u064e\u0648\u064e\u0641\u064e\u0651\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u0627\u064e \u062a\u064e\u062d\u0652\u0631\u0650\u0645\u0652\u0646\u064e\u0627 \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f \u0648\u064e\u0644\u0627\u064e \u062a\u064f\u0636\u0650\u0644\u064e\u0651\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064f.",
      transliteration: "",
      translation: "O Allaah, forgive our living and our dead, those present and those absent, our young and our old, our males and our females. O Allaah, whom amongst us You keep alive, then let such a life be upon Islaam, and whom amongst us You take unto Yourself, then let such a death be upon faith. O Allaah, do not deprive us of his reward and do not let us stray after him.",
      commonName: "Supplication for the deceased at the funeral prayer (2)",
      notes: "",
      repetition: "At the funeral prayer",
      source: "Hisnul Muslim, Section 51, Item 149",
    ),
    OtherDua(
      id: 109,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u064e\u0651 \u0641\u064f\u0644\u0627\u064e\u0646\u064e \u0628\u0652\u0646\u064e \u0641\u064f\u0644\u0627\u064e\u0646\u064d \u0641\u0650\u064a \u0630\u0650\u0645\u064e\u0651\u062a\u0650\u0643\u064e\u060c \u0648\u064e\u062d\u064e\u0628\u0652\u0644\u0650 \u062c\u0650\u0648\u064e\u0627\u0631\u0650\u0643\u064e\u060c \u0641\u064e\u0642\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0648\u064e\u0641\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0642\u0650\u0651\u060c \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0647\u064f \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u064e\u0651\u062d\u0650\u064a\u0645\u064f.",
      transliteration: "",
      translation: "O Allaah, so-and-so is under Your care and protection so protect him from the trial of the grave and torment of the Fire. Indeed You are faithful and truthful. Forgive and have mercy upon him, surely You are The Oft-Forgiving, The Most-Merciful.",
      commonName: "Supplication for the deceased at the funeral prayer (3)",
      notes: "",
      repetition: "At the funeral prayer",
      source: "Hisnul Muslim, Section 51, Item 150",
    ),
    OtherDua(
      id: 110,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u0648\u064e\u0627\u0628\u0652\u0646\u064f \u0623\u064e\u0645\u064e\u062a\u0650\u0643\u064e \u0627\u062d\u0652\u062a\u064e\u0627\u062c\u064e \u0625\u0650\u0644\u064e\u0649 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u063a\u064e\u0646\u0650\u064a\u064c\u0651 \u0639\u064e\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0647\u0650\u060c \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0627\u064b \u0641\u064e\u0632\u0650\u062f\u0652 \u0641\u0650\u064a \u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0633\u0650\u064a\u0626\u0627\u064b \u0641\u064e\u062a\u064e\u062c\u064e\u0627\u0648\u064e\u0632\u0652 \u0639\u064e\u0646\u0652\u0647\u064f.",
      transliteration: "",
      translation: "O Allaah, Your servant and the son of Your maidservant is in need of Your mercy and You are without need of his punishment. If he was righteous then increase his reward and if he was wicked then look over his sins.",
      commonName: "Supplication for the deceased at the funeral prayer (4)",
      notes: "",
      repetition: "At the funeral prayer",
      source: "Hisnul Muslim, Section 51, Item 151",
    ),
    OtherDua(
      id: 101,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0644\u0652\u062d\u0650\u0642\u0652\u0646\u0650\u064a \u0628\u0650\u0627\u0644\u0631\u064e\u0651\u0641\u0650\u064a\u0642\u0650 \u0627\u0644\u0623\u064e\u0639\u0652\u0644\u064e\u0649.",
      transliteration: "",
      translation: "O Allaah, forgive me, have mercy upon me and unite me with the highest companions.",
      commonName: "Supplication of the sick who have renounced all hope of life",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 47, Item 142",
    ),
    OtherDua(
      id: 102,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0625\u0650\u0646\u064e\u0651 \u0644\u0650\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0644\u064e\u0633\u064e\u0643\u064e\u0631\u064e\u0627\u062a\u064d.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah, death does indeed contain agony.",
      commonName: "Supplication of the sick who have renounced all hope of life (2)",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 47, Item 143",
    ),
    OtherDua(
      id: 103,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e\u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0644\u0627\u064e \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u0627\u064e \u0642\u064f\u0648\u064e\u0651\u0629\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah and Allaah is the greatest... None has the right to be worshipped except Allaah and there is no might and no power except with Allaah.",
      commonName: "Instruction for the one nearing death (talqeen)",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 48, Item 144",
    ),
    OtherDua(
      id: 104,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah.",
      commonName: "Instruction for the one nearing death \u2014 the words themselves",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 48, Item 145",
    ),
    OtherDua(
      id: 105,
      arabicOnly: "\u0625\u0650\u0646\u064e\u0651\u0627 \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064f\u062c\u064f\u0631\u0652\u0646\u0650\u064a \u0641\u0650\u064a \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u062a\u0650\u064a \u0648\u064e\u0627\u062e\u0652\u0644\u064f\u0641\u0652 \u0644\u0650\u064a \u062e\u064e\u064a\u0652\u0631\u0627\u064b \u0645\u0650\u0646\u0652\u0647\u064e\u0627.",
      transliteration: "",
      translation: "To Allaah we belong and unto Him is our return. O Allaah, recompense me for my affliction and replace it for me with something better.",
      commonName: "Supplication for one afflicted by a calamity",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 49, Item 146",
    ),
    OtherDua(
      id: 106,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0640 -\u0641\u0644\u0627\u0646 \u0628\u0627\u0633\u0645\u0647- \u0648\u064e\u0627\u0631\u0652\u0641\u064e\u0639\u0652 \u062f\u064e\u0631\u064e\u062c\u064e\u062a\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0647\u0652\u062f\u0650\u064a\u0650\u0651\u064a\u0646\u064e \u0648\u064e\u0627\u062e\u0652\u0644\u064f\u0641\u0652\u0647\u064f \u0641\u0650\u064a \u0639\u064e\u0642\u0650\u0628\u0650\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e\u060c \u0648\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f \u064a\u064e\u0627\u0631\u064e\u0628\u064e\u0651 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e\u060c \u0648\u064e\u0627\u0641\u0652\u0633\u064e\u062d\u0652 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0642\u064e\u0628\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0646\u064e\u0648\u0650\u0651\u0631\u0652 \u0644\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650.",
      transliteration: "",
      translation: "O Allaah, forgive -name of deceased- and raise his rank among the rightly guided, and be a successor to whom he has left behind, and forgive us and him O Lord of the worlds, and make spacious his grave and illuminate it for him.",
      commonName: "Supplication when closing the eyes of the deceased",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 50, Item 147",
    ),
    OtherDua(
      id: 95,
      arabicOnly: "\u0642\u064e\u062f\u064e\u0651\u0631\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0641\u064e\u0639\u064e\u0644\u064e.",
      transliteration: "",
      translation: "Allaah has decreed and what He wills, He does.",
      commonName: "Supplication when stricken with a mishap or overtaken by an affair (1)",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 43, Item 136",
    ),
    OtherDua(
      id: 96,
      arabicOnly: "\u062d\u064e\u0633\u0652\u0628\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0648\u064e\u0643\u0650\u064a\u0644\u064f.",
      transliteration: "",
      translation: "Allaah is sufficient for me, and how fine a trustee (He is).",
      commonName: "Supplication when stricken with a mishap or overtaken by an affair (2)",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 43, Item 137",
    ),
    OtherDua(
      id: 97,
      arabicOnly: "\u0623\u064f\u0639\u0650\u064a\u0630\u064f\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u062a\u064e\u0651\u0627\u0645\u064e\u0651\u0629\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064d \u0648\u064e\u0647\u064e\u0627\u0645\u064e\u0651\u0629\u064d \u0648\u064e\u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0650\u0651 \u0639\u064e\u064a\u0652\u0646\u064d \u0644\u0627\u064e\u0645\u064e\u0651\u0629\u064d.",
      transliteration: "",
      translation: "I commend you two to the protection of Allaah's perfect words from every devil, vermin, and every evil eye.",
      commonName: "Placing children under Allaah's protection",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 44, Item 138",
    ),
    OtherDua(
      id: 98,
      arabicOnly: "\u0644\u0627\u064e \u0628\u064e\u0623\u0652\u0633\u064e \u0637\u064e\u0647\u064f\u0648\u0631\u064c \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f.",
      transliteration: "",
      translation: "Never mind, may it (the sickness) be a purification, if Allaah wills.",
      commonName: "Supplication when visiting the sick (1)",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 45, Item 139",
    ),
    OtherDua(
      id: 99,
      arabicOnly: "\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064e \u0631\u064e\u0628\u064e\u0651 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0641\u0650\u064a\u064e\u0643\u064e. (\u0633\u0628\u0639 \u0645\u0631\u0627\u062a)",
      transliteration: "",
      translation: "I ask Allaah The Supreme, Lord of the magnificent throne to cure you.",
      commonName: "Supplication when visiting the sick (2)",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 45, Item 140",
    ),
    OtherDua(
      id: 81,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u064e\u0651\u0627 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0643\u064e \u0641\u0650\u064a \u0646\u064f\u062d\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0646\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064f\u0631\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652.",
      transliteration: "",
      translation: "O Allaah, we place You before them and we take refuge in You from their evil.",
      commonName: "Supplication upon encountering an enemy or those of authority (1)",
      notes: "",
      repetition: "Upon encountering an enemy or those of authority",
      source: "Hisnul Muslim, Section 36, Item 122",
    ),
    OtherDua(
      id: 82,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0636\u064f\u062f\u0650\u064a\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0646\u064e\u0635\u0650\u064a\u0631\u0650\u064a\u060c \u0628\u0650\u0643\u064e \u0623\u064e\u062c\u064f\u0648\u0644\u064f \u0648\u064e\u0628\u0650\u0643\u064e \u0623\u064e\u0635\u064f\u0648\u0644\u064f \u0648\u064e\u0628\u0650\u0643\u064e \u0623\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f.",
      transliteration: "",
      translation: "O Allaah, You are my supporter and You are my helper, by You I move and by You I attack and by You I battle.",
      commonName: "Supplication upon encountering an enemy or those of authority (2)",
      notes: "",
      repetition: "Upon encountering an enemy or those of authority",
      source: "Hisnul Muslim, Section 36, Item 123",
    ),
    OtherDua(
      id: 83,
      arabicOnly: "\u062d\u064e\u0633\u0652\u0628\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0648\u064e\u0643\u0650\u064a\u0644\u064f.",
      transliteration: "",
      translation: "Allaah is sufficient for us, and how fine a trustee (He is).",
      commonName: "Supplication upon encountering an enemy or those of authority (3)",
      notes: "",
      repetition: "Upon encountering an enemy or those of authority",
      source: "Hisnul Muslim, Section 36, Item 124",
    ),
    OtherDua(
      id: 84,
      arabicOnly: "",
      transliteration: "",
      translation: "He should seek refuge in Allaah; He should renounce that which is causing such doubt.",
      commonName: "Guidance for one afflicted with doubt in his faith (1)",
      notes: "Instructional guidance rather than a spoken supplication text.",
      repetition: "",
      source: "Hisnul Muslim, Section 37, Item 125",
    ),
    OtherDua(
      id: 85,
      arabicOnly: "\u0622\u0645\u064e\u0646\u0652\u062a\u064f \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650.",
      transliteration: "",
      translation: "I have believed in Allaah and His Messengers.",
      commonName: "Supplication for one afflicted with doubt in his faith (2)",
      notes: "",
      repetition: "For doubt in faith",
      source: "Hisnul Muslim, Section 37, Item 126",
    ),
    OtherDua(
      id: 86,
      arabicOnly: "\u0647\u064f\u0648\u064e \u0627\u0644\u0623\u064e\u0648\u064e\u0651\u0644\u064f \u0648\u064e\u0627\u0644\u0622\u062e\u0650\u0631\u064f \u0648\u064e\u0627\u0644\u0638\u064e\u0651\u0627\u0647\u0650\u0631\u064f \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0646\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c.",
      transliteration: "",
      translation: "He is The First and The Last, Ath-THaahir and Al-Baatin and He knows well all things.",
      commonName: "Supplication for one afflicted with doubt in his faith (3)",
      notes: "He should also recite this verse.",
      repetition: "For doubt in faith",
      source: "Hisnul Muslim, Section 37, Item 127; Quran, Al-Hadeed 57:3",
    ),
    OtherDua(
      id: 87,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0643\u0652\u0641\u0650\u0646\u0650\u064a \u0628\u0650\u062d\u064e\u0644\u0627\u064e\u0644\u0650\u0643\u064e \u0639\u064e\u0646\u0652 \u062d\u064e\u0631\u064e\u0627\u0645\u0650\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u063a\u0652\u0646\u0650\u0646\u0650\u064a \u0628\u0650\u0641\u064e\u0636\u0652\u0644\u0650\u0643\u064e \u0639\u064e\u0645\u064e\u0651\u0646\u0652 \u0633\u0650\u0648\u064e\u0627\u0643\u064e.",
      transliteration: "",
      translation: "O Allaah, make what is lawful enough for me, as opposed to what is unlawful, and spare me by Your grace, of need of others.",
      commonName: "Settling a debt",
      notes: "",
      repetition: "For settling a debt",
      source: "Hisnul Muslim, Section 38, Item 128",
    ),
    OtherDua(
      id: 88,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u0645\u0650\u0651 \u0648\u064e\u0627\u0644\u0652\u062d\u064f\u0632\u0652\u0646\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u062c\u0652\u0632\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0633\u064e\u0644\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0628\u0652\u0646\u0650\u060c \u0648\u064e\u0636\u064e\u0644\u0652\u0639\u0650 \u0627\u0644\u062f\u064e\u0651\u064a\u0652\u0646\u0650 \u0648\u064e\u063a\u064e\u0644\u064e\u0628\u064e\u0629\u0650 \u0627\u0644\u0631\u0650\u0651\u062c\u064e\u0627\u0644\u0650.",
      transliteration: "",
      translation: "O Allaah, I take refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being overpowered by men.",
      commonName: "Settling a debt (2)",
      notes: "",
      repetition: "For settling a debt",
      source: "Hisnul Muslim, Section 38, Item 129",
    ),
    OtherDua(
      id: 89,
      arabicOnly: "",
      transliteration: "",
      translation: "'Uthmaan Ibn Al-'Aas narrated: I said 'O Messenger of Allaah, verily the devil comes between me and my prayer and recitation making me confused.' The Messenger of Allaah replied 'That is a devil called Khanzab, so if you sense his presence then seek refuge in Allaah from him and spit on your left side three times.'",
      commonName: "Supplication for one afflicted by whisperings in prayer or recitation",
      notes: "Narrative/instructional guidance rather than a fixed recited text.",
      repetition: "",
      source: "Hisnul Muslim, Section 39, Item 130",
    ),
    OtherDua(
      id: 90,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u0627\u064e \u0633\u064e\u0647\u0652\u0644\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u062a\u064e\u0647\u064f \u0633\u064e\u0647\u0652\u0644\u0627\u064b\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0652\u062d\u064e\u0632\u0652\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0634\u0650\u0626\u0652\u062a\u064e \u0633\u064e\u0647\u0652\u0644\u0627\u064b.",
      transliteration: "",
      translation: "O Allaah, there is no ease except in that which You have made easy, and You make the difficulty, if You wish, easy.",
      commonName: "Supplication for one whose affairs have become difficult",
      notes: "",
      repetition: "When affairs have become difficult",
      source: "Hisnul Muslim, Section 40, Item 131",
    ),
    OtherDua(
      id: 91,
      arabicOnly: "",
      transliteration: "",
      translation: "Any servant who commits a sin and as a result, performs ablution, prays two units of prayer (i.e. two rak'ats) and then seeks Allaah's forgiveness, Allaah would forgive him.",
      commonName: "Guidance upon committing a sin",
      notes: "Instructional guidance rather than a fixed spoken supplication text.",
      repetition: "Upon committing a sin",
      source: "Hisnul Muslim, Section 41, Item 132",
    ),
    OtherDua(
      id: 71,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0647\u0652\u062f\u0650\u0646\u0650\u064a \u0641\u0650\u064a\u0645\u064e\u0646\u0652 \u0647\u064e\u062f\u064e\u064a\u0652\u062a\u064e\u060c \u0648\u064e\u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a \u0641\u0650\u064a\u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u0641\u064e\u064a\u0652\u062a\u064e\u060c \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u064e\u0651\u0646\u0650\u064a \u0641\u0650\u064a\u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u064e\u0651\u064a\u0652\u062a\u064e\u060c \u0648\u064e\u0628\u064e\u0627\u0631\u0650\u0643\u0652 \u0644\u0650\u064a \u0641\u0650\u064a\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0637\u064e\u064a\u0652\u062a\u064e\u060c \u0648\u064e\u0642\u0650\u0646\u0650\u064a \u0634\u064e\u0631\u064e\u0651 \u0645\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u0652\u062a\u064e\u060c \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0643\u064e \u062a\u064e\u0642\u0652\u0636\u0650\u064a \u0648\u064e\u0644\u0627\u064e \u064a\u064f\u0642\u0652\u0636\u064e\u0649 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e\u060c \u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0644\u0627\u064e \u064a\u064e\u0630\u0650\u0644\u064f\u0651 \u0645\u064e\u0646\u0652 \u0648\u064e\u0627\u0644\u064e\u064a\u0652\u062a\u064e\u060c [\u0648\u064e\u0644\u0627\u064e \u064a\u064e\u0639\u0650\u0632\u064f\u0651 \u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u062f\u064e\u064a\u0652\u062a\u064e]\u060c \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u0631\u064e\u0628\u064e\u0651\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u064a\u0652\u062a\u064e.",
      transliteration: "",
      translation: "O Allaah, guide me along with those whom You have guided, pardon me along with those whom You have pardoned, be an ally to me along with those whom You are an ally to and bless for me that which You have bestowed. Protect me from the evil You have decreed for verily You decree and none can decree over You. For surety, he whom you show allegiance to is never abased and he whom You take as an enemy is never honoured and mighty. O our Lord, Blessed and Exalted are You.",
      commonName: "Qunuut Al-Witr",
      notes: "Supplication made before or after bowing in the witr prayer.",
      repetition: "In the witr prayer",
      source: "Hisnul Muslim, Section 32, Item 112",
    ),
    OtherDua(
      id: 72,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u0650\u0636\u064e\u0627\u0643\u064e \u0645\u0650\u0646\u0652 \u0633\u064e\u062e\u064e\u0637\u0650\u0643\u064e\u060c \u0648\u064e\u0628\u0650\u0645\u064f\u0639\u064e\u0627\u0641\u064e\u0627\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064f\u0642\u064f\u0648\u0628\u064e\u062a\u0650\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652\u0643\u064e\u060c \u0644\u0627\u064e \u0623\u064f\u062d\u0652\u0635\u0650\u064a \u062b\u064e\u0646\u064e\u0627\u0621\u064b \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062b\u0652\u0646\u064e\u064a\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e.",
      transliteration: "",
      translation: "O Allaah, I take refuge within Your pleasure from Your displeasure and within Your pardon from Your punishment, and I take refuge in You from You. I cannot enumerate Your praise. You are as You have praised Yourself.",
      commonName: "Qunuut Al-Witr (2)",
      notes: "",
      repetition: "In the witr prayer",
      source: "Hisnul Muslim, Section 32, Item 113",
    ),
    OtherDua(
      id: 73,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u064a\u064e\u0651\u0627\u0643\u064e \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u060c \u0648\u064e\u0644\u064e\u0643\u064e \u0646\u064f\u0635\u064e\u0644\u0650\u0651\u064a \u0648\u064e\u0646\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u060c \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0646\u064e\u0633\u0652\u0639\u064e\u0649 \u0648\u064e\u0646\u064e\u062d\u0652\u0641\u0650\u062f\u064f\u060c \u0646\u064e\u0631\u0652\u062c\u064f\u0648 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e\u0643\u064e\u060c \u0648\u064e\u0646\u064e\u062e\u0652\u0634\u064e\u0649 \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0643\u064e\u060c \u0625\u0650\u0646\u064e\u0651 \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u064f\u0644\u0652\u062d\u064e\u0642\u064c. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u064e\u0651\u0627 \u0646\u064e\u0633\u0652\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0643\u064e\u060c \u0648\u064e\u0646\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0643\u064e\u060c \u0648\u064e\u0646\u064f\u062b\u0652\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u060c \u0648\u064e\u0644\u0627\u064e \u0646\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0643\u064e\u060c \u0648\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0643\u064e\u060c \u0648\u064e\u0646\u064e\u062e\u0652\u0636\u064e\u0639\u064f \u0644\u064e\u0643\u064e\u060c \u0648\u064e\u0646\u064e\u062e\u0652\u0644\u064e\u0639\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0643\u064e.",
      transliteration: "",
      translation: "O Allaah, it is You we worship, and unto You we pray and prostrate, and towards You we hasten and You we serve. We hope for Your mercy and fear Your punishment, verily Your punishment will fall upon the disbelievers. O Allaah, we seek Your aid and ask Your pardon, we praise You with all good and do not disbelieve in You. We believe in You and submit unto You, and we disown and reject those who disbelieve in You.",
      commonName: "Qunuut Al-Witr (3)",
      notes: "",
      repetition: "In the witr prayer",
      source: "Hisnul Muslim, Section 32, Item 114",
    ),
    OtherDua(
      id: 74,
      arabicOnly: "\ufd3f\u0633\u064e\u0628\u0650\u0651\u062d\u0650 \u0627\u0633\u0652\u0645\u064e \u0631\u064e\u0628\u0650\u0651\u0643\u064e \u0627\u0644\u0623\u064e\u0639\u0652\u0644\u064e\u0649...\ufd3e [Al-A'laa]\u060c \ufd3f\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u064f\u0651\u0647\u064e\u0627 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e...\ufd3e [Al-Kaafiruun]\u060c \ufd3f\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c...\ufd3e [Al-Ikhlaas]. \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u0650 \u0627\u0644\u0652\u0642\u064f\u062f\u064f\u0651\u0648\u0633\u0650. (\u062b\u0644\u0627\u062b\u0627\u064b) \u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0652\u0645\u064e\u0644\u0627\u064e\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0631\u064f\u0651\u0648\u062d\u0650.",
      transliteration: "",
      translation: "Recitation of Surah Al-A'laa, Surah Al-Kaafiruun, and Surah Al-Ikhlaas during the witr prayer. After giving salaam he would supplicate three times: How perfect The King, The Holy One is. On the third time he would raise his voice, elongate it and add: Lord of the angels and the Ruuh (i.e. Jibraa'eel).",
      commonName: "Remembrance immediately after salaam of the witr prayer",
      notes: "",
      repetition: "Three times, immediately after salaam of witr",
      source: "Hisnul Muslim, Section 33, Item 115",
    ),
    OtherDua(
      id: 75,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u0627\u0628\u0652\u0646\u064f \u0639\u064e\u0628\u0652\u062f\u0650\u0643\u064e \u0627\u0628\u0652\u0646\u064f \u0623\u064e\u0645\u064e\u062a\u0650\u0643\u064e \u0646\u064e\u0627\u0635\u0650\u064a\u064e\u062a\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0643\u064e\u060c \u0645\u064e\u0627\u0636\u064d \u0641\u0650\u064a\u064e\u0651 \u062d\u064f\u0643\u0652\u0645\u064f\u0643\u064e\u060c \u0639\u064e\u062f\u0652\u0644\u064c \u0641\u0650\u064a\u064e\u0651 \u0642\u064e\u0636\u064e\u0627\u0624\u064f\u0643\u064e\u060c \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0628\u0650\u0643\u064f\u0644\u0650\u0651 \u0627\u0633\u0652\u0645\u064d \u0647\u064f\u0648\u064e \u0644\u064e\u0643\u064e \u0633\u064e\u0645\u064e\u0651\u064a\u0652\u062a\u064e \u0628\u0650\u0647\u0650 \u0646\u064e\u0641\u0652\u0633\u064e\u0643\u064e\u060c \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u0651\u0645\u0652\u062a\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u0627\u064b \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0642\u0650\u0643\u064e\u060c \u0623\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u062a\u064e\u0647\u064f \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u0650\u0643\u064e\u060c \u0623\u064e\u0648\u0650 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u062b\u064e\u0631\u0652\u062a\u064e \u0628\u0650\u0647\u0650 \u0641\u0650\u064a \u0639\u0650\u0644\u0652\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e\u060c \u0623\u064e\u0646\u0652 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0631\u064e\u0628\u0650\u064a\u0639\u064e \u0642\u064e\u0644\u0652\u0628\u0650\u064a\u060c \u0648\u064e\u0646\u064f\u0648\u0631\u064e \u0635\u064e\u062f\u0652\u0631\u0650\u064a\u060c \u0648\u064e\u062c\u064e\u0644\u0627\u064e\u0621\u064e \u062d\u064f\u0632\u0652\u0646\u0650\u064a\u060c \u0648\u064e\u0630\u064e\u0647\u064e\u0627\u0628\u064e \u0647\u064e\u0645\u0650\u0651\u064a.",
      transliteration: "",
      translation: "O Allaah, I am Your servant, son of Your servant, son of Your maidservant, my forelock is in Your hand, Your command over me is forever executed and Your decree over me is just. I ask You by every name belonging to You which You named Yourself with, or revealed in Your Book, or You taught to any of Your creation, or You have preserved in the knowledge of the unseen with You, that You make the Qur'aan the life of my heart and the light of my breast, and a departure for my sorrow and a release for my anxiety.",
      commonName: "Supplication for anxiety and sorrow (1)",
      notes: "",
      repetition: "For anxiety and sorrow",
      source: "Hisnul Muslim, Section 34, Item 116",
    ),
    OtherDua(
      id: 76,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u0645\u0650\u0651 \u0648\u064e\u0627\u0644\u0652\u062d\u064f\u0632\u0652\u0646\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u062c\u0652\u0632\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0633\u064e\u0644\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0628\u0652\u0646\u0650\u060c \u0648\u064e\u0636\u064e\u0644\u0652\u0639\u0650 \u0627\u0644\u062f\u064e\u0651\u064a\u0652\u0646\u0650 \u0648\u064e\u063a\u064e\u0644\u064e\u0628\u064e\u0629\u0650 \u0627\u0644\u0631\u0650\u0651\u062c\u064e\u0627\u0644\u0650.",
      transliteration: "",
      translation: "O Allaah, I take refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being overpowered by men.",
      commonName: "Supplication for anxiety and sorrow (2)",
      notes: "",
      repetition: "For anxiety and sorrow",
      source: "Hisnul Muslim, Section 34, Item 117",
    ),
    OtherDua(
      id: 77,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0644\u0650\u064a\u0645\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u0650.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah the Magnificent, the Forbearing. None has the right to be worshipped except Allaah, Lord of the magnificent throne. None has the right to be worshipped except Allaah, Lord of the heavens, Lord of the Earth and Lord of the noble throne.",
      commonName: "Supplication for one in distress (1)",
      notes: "",
      repetition: "For one in distress",
      source: "Hisnul Muslim, Section 35, Item 118",
    ),
    OtherDua(
      id: 78,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e\u0643\u064e \u0623\u064e\u0631\u0652\u062c\u064f\u0648 \u0641\u064e\u0644\u0627\u064e \u062a\u064e\u0643\u0650\u0644\u0652\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0637\u064e\u0631\u0652\u0641\u064e\u0629\u064e \u0639\u064e\u064a\u0652\u0646\u064d\u060c \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u0652 \u0644\u0650\u064a \u0634\u064e\u0623\u0652\u0646\u0650\u064a \u0643\u064f\u0644\u064e\u0651\u0647\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e.",
      transliteration: "",
      translation: "O Allaah, it is Your mercy that I hope for, so do not leave me in charge of my affairs even for a blink of an eye and rectify for me all of my affairs. None has the right to be worshipped except You.",
      commonName: "Supplication for one in distress (2)",
      notes: "",
      repetition: "For one in distress",
      source: "Hisnul Muslim, Section 35, Item 119",
    ),
    OtherDua(
      id: 79,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0625\u0650\u0646\u0650\u0651\u064a \u0643\u064f\u0646\u0652\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u064e\u0651\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e.",
      transliteration: "",
      translation: "None has the right to be worshipped except You. How perfect You are, verily I was among the wrong-doers.",
      commonName: "Supplication for one in distress (3)",
      notes: "",
      repetition: "For one in distress",
      source: "Hisnul Muslim, Section 35, Item 120",
    ),
    OtherDua(
      id: 80,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0631\u064e\u0628\u0650\u0651\u064a \u0644\u0627\u064e \u0623\u064f\u0634\u0652\u0631\u0650\u0643\u064f \u0628\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u0627\u064b.",
      transliteration: "",
      translation: "Allaah, Allaah is my Lord, I do not associate anything with Him.",
      commonName: "Supplication for one in distress (4)",
      notes: "",
      repetition: "For one in distress",
      source: "Hisnul Muslim, Section 35, Item 121",
    ),
    OtherDua(
      id: 67,
      arabicOnly: "\u0644\u0627\u064e\u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0652\u0642\u064e\u0647\u064e\u0651\u0627\u0631\u064f\u060c \u0631\u064e\u0628\u064f\u0651 \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u063a\u064e\u0641\u064e\u0651\u0627\u0631\u064f.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah, The One, Al-Qahhaar. Lord of the heavens and the Earth and all between them, The Exalted in Might, The Oft-Forgiving.",
      commonName: "Supplication when turning over during the night",
      notes: "Narrated by 'Aaishah: the Messenger of Allaah (peace be upon him) used to say this at night if he turned during sleep. Al-Qahhaar: The One Who has subdued all of creation and Whom all of creation are subservient to.",
      repetition: "When turning over during sleep at night",
      source: "Hisnul Muslim, Section 29, Item 108",
    ),
    OtherDua(
      id: 68,
      arabicOnly: "\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u062a\u064e\u0651\u0627\u0645\u064e\u0651\u0627\u062a\u0650 \u0645\u0650\u0646\u0652 \u063a\u064e\u0636\u064e\u0628\u0650\u0647\u0650 \u0648\u064e\u0639\u0650\u0642\u064e\u0627\u0628\u0650\u0647\u0650\u060c \u0648\u064e\u0634\u064e\u0631\u0650\u0651 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0632\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u064e\u0651\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0652\u0636\u064f\u0631\u064f\u0648\u0646\u0650.",
      transliteration: "",
      translation: "I take refuge in the perfect words of Allaah from His anger and punishment, and from the evil of His servants, and from the madness and appearance of devils.",
      commonName: "Supplication upon experiencing unrest, fear, or apprehensiveness during sleep",
      notes: "",
      repetition: "Upon experiencing unrest, fear, apprehensiveness or the like during sleep",
      source: "Hisnul Muslim, Section 30, Item 109",
    ),
    OtherDua(
      id: 69,
      arabicOnly: "",
      transliteration: "",
      translation: "The righteous dream is from Allaah and the bad dream is from the devil, so if anyone sees something which pleases him then he should only relate it to one whom he loves...",
      commonName: "Guidance upon seeing a good dream",
      notes: "",
      repetition: "",
      source: "Hisnul Muslim, Section 31, Item 110",
    ),
    OtherDua(
      id: 70,
      arabicOnly: "",
      transliteration: "",
      translation: "Summary of what to do upon having a bad dream: spit on your left three times; seek refuge in Allaah from shaytaan and the evil of what you saw; do not relate it to anyone; turn and sleep on the opposite side to which you were sleeping on previously; get up and pray if you so desire.",
      commonName: "Guidance upon seeing a bad dream",
      notes: "Instructional guidance rather than a spoken supplication text.",
      repetition: "",
      source: "Hisnul Muslim, Section 31, Item 111",
    ),
    OtherDua(
      id: 66,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u062a\u064e\u062e\u0650\u064a\u0631\u064f\u0643\u064e \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u062a\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u0642\u064f\u062f\u0652\u0631\u064e\u062a\u0650\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650\u060c \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0643\u064e \u062a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0648\u064e\u0644\u0627\u064e \u0623\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u060c \u0648\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0648\u064e\u0644\u0627\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u060c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u0627\u064e\u0651\u0645\u064f \u0627\u0644\u0652\u063a\u064f\u064a\u064f\u0648\u0628\u0650. \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u064e\u0651 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0623\u064e\u0645\u0652\u0631\u064e -\u0648\u064a\u0633\u0645\u0651\u064a \u062d\u0627\u062c\u062a\u0647- \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u064a \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0639\u064e\u0627\u0634\u0650\u064a \u0648\u064e\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u0650 \u0623\u064e\u0645\u0652\u0631\u0650\u064a\u060c \u0641\u064e\u0627\u0642\u0652\u062f\u0650\u0631\u0652\u0647\u064f \u0644\u0650\u064a \u0648\u064e\u064a\u064e\u0633\u0650\u0651\u0631\u0652\u0647\u064f \u0644\u0650\u064a \u062b\u064f\u0645\u064e\u0651 \u0628\u064e\u0627\u0631\u0650\u0643\u0652 \u0644\u0650\u064a \u0641\u0650\u064a\u0647\u0650\u060c \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u064e\u0651 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0623\u064e\u0645\u0652\u0631\u064e \u0634\u064e\u0631\u064c\u0651 \u0644\u0650\u064a \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0639\u064e\u0627\u0634\u0650\u064a \u0648\u064e\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u0650 \u0623\u064e\u0645\u0652\u0631\u0650\u064a \u0641\u064e\u0627\u0635\u0652\u0631\u0650\u0641\u0652\u0647\u064f \u0639\u064e\u0646\u0650\u0651\u064a \u0648\u064e\u0627\u0635\u0652\u0631\u0650\u0641\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0647\u064f\u060c \u0648\u064e\u0627\u0642\u0652\u062f\u0650\u0631\u0652 \u0644\u0650\u064a\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e \u062d\u064e\u064a\u0652\u062b\u064f \u0643\u064e\u0627\u0646\u064e \u062b\u064f\u0645\u064e\u0651 \u0623\u064e\u0631\u0652\u0636\u0650\u0646\u0650\u064a \u0628\u0650\u0647\u0650.",
      transliteration: "",
      translation: "O Allaah, I seek Your counsel by Your knowledge and by Your power I seek strength and I ask You from Your immense favour, for verily You are able while I am not and verily You know while I do not and You are the Knower of the unseen. O Allaah, if You know this affair -and here he mentions his need- to be good for me in relation to my religion, my life, and end, then decree and facilitate it for me, and bless me with it, and if You know this affair to be ill for me towards my religion, my life, and end, then remove it from me and remove me from it, and decree for me what is good wherever it be and make me satisfied with such.",
      commonName: "Supplication for seeking guidance (Al-Istikhaarah)",
      notes: "The Prophet (peace be upon him) would instruct the Companions to pray for guidance in all their concerns, just as he would teach a chapter from the Qur'aan. One who seeks guidance from his Creator and consults his fellow believers and then remains firm in his resolve does not regret, per Aal 'Imraan 3:159.",
      repetition: "Once, after praying two rak'ah of naafilah (Istikhaarah prayer)",
      source: "Hisnul Muslim, Section 26, Item 74",
    ),
    OtherDua(
      id: 59,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u0627\u064e \u0645\u064e\u0627\u0646\u0650\u0639\u064e \u0644\u0650\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0637\u064e\u064a\u0652\u062a\u064e\u060c \u0648\u064e\u0644\u0627\u064e \u0645\u064f\u0639\u0652\u0637\u0650\u064a\u064e \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u0652\u062a\u064e\u060c \u0648\u064e\u0644\u0627\u064e \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u062f\u0650\u0651 \u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u062f\u064f\u0651.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent. O Allaah, none can prevent what You have willed to bestow and none can bestow what You have willed to prevent, and no wealth or majesty can benefit anyone, as from You is all wealth and majesty.",
      commonName: "Remembrance after salaam (2)",
      notes: "",
      repetition: "Once, after salaam",
      source: "Hisnul Muslim, Section 25, Item 67",
    ),
    OtherDua(
      id: 60,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e\u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c\u060c \u0644\u0627\u064e \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u0627\u064e \u0642\u064f\u0648\u064e\u0651\u0629\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u060c \u0648\u064e\u0644\u0627\u064e \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0625\u0650\u0644\u0627\u064e\u0651 \u0625\u0650\u064a\u064e\u0651\u0627\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0646\u0650\u0651\u0639\u0652\u0645\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u062b\u064e\u0651\u0646\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0650\u0651\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent. There is no might nor power except with Allaah, none has the right to be worshipped except Allaah and we worship none except Him. For Him is all favour, grace, and glorious praise. None has the right to be worshipped except Allaah and we are sincere in faith and devotion to Him although the disbelievers detest it.",
      commonName: "Remembrance after salaam (3)",
      notes: "",
      repetition: "Once, after salaam",
      source: "Hisnul Muslim, Section 25, Item 68",
    ),
    OtherDua(
      id: 61,
      arabicOnly: "\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f. (\u062b\u0644\u0627\u062b\u0627\u064b \u0648\u062b\u0644\u0627\u062b\u064a\u0646) \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e\u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c.",
      transliteration: "",
      translation: "How perfect Allaah is, all praise is for Allaah, and Allaah is the greatest. (thirty-three times) None has the right to be worshipped except Allaah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent.",
      commonName: "Remembrance after salaam (4) - Tasbeeh",
      notes: "",
      repetition: "Thirty-three times each (subhaanAllaah, alhamdulillah, Allaahu akbar), then once the final phrase, completing one hundred",
      source: "Hisnul Muslim, Section 25, Item 69",
    ),
    OtherDua(
      id: 62,
      arabicOnly: "\ufd3f\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c...\ufd3e [Al-Ikhlaas]\u060c \ufd3f\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0652\u0641\u064e\u0644\u064e\u0642\u0650...\ufd3e [Al-Falaq]\u060c \ufd3f\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650...\ufd3e [An-Naas]",
      transliteration: "",
      translation: "Recitation of Surah Al-Ikhlaas, Surah Al-Falaq, and Surah An-Naas.",
      commonName: "Recitation of the three Quls after prayer",
      notes: "Recited once after Thuhr, 'Asr and 'Ishaa' prayers, and thrice after Fajr and Maghrib.",
      repetition: "Once after Thuhr, 'Asr, 'Ishaa'; three times after Fajr and Maghrib",
      source: "Hisnul Muslim, Section 25, Item 70",
    ),
    OtherDua(
      id: 63,
      arabicOnly: "\ufd3f\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064f\u0651 \u0627\u0644\u0652\u0642\u064e\u064a\u064f\u0651\u0648\u0645\u064f \u0644\u0627\u064e \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u0627\u064e \u0646\u064e\u0648\u0652\u0645\u064c...\ufd3e [Al-Baqarah:255]",
      transliteration: "",
      translation: "Recitation of Ayat-ul-Kursiyy (the verse of the Footstool).",
      commonName: "Recitation of Ayat-ul-Kursiyy after each prayer",
      notes: "It is from the sunnah to recite the verse of the Footstool (Ayat-ul-Kursiyy) after each prayer.",
      repetition: "Once, after each prayer",
      source: "Hisnul Muslim, Section 25, Item 71; Quran, Al-Baqarah 2:255",
    ),
    OtherDua(
      id: 64,
      arabicOnly: "\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e\u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c.",
      transliteration: "",
      translation: "None has the right to be worshipped except Allaah, alone, without partner, to Him belongs all sovereignty and praise, He gives life and causes death and He is over all things omnipotent.",
      commonName: "Remembrance after salaam (5)",
      notes: "",
      repetition: "Ten times, after the maghrib and fajr prayers",
      source: "Hisnul Muslim, Section 25, Item 72",
    ),
    OtherDua(
      id: 65,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0639\u0650\u0644\u0652\u0645\u0627\u064b \u0646\u064e\u0627\u0641\u0650\u0639\u0627\u064b \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u0627\u064b \u0637\u064e\u064a\u0650\u0651\u0628\u0627\u064b\u060c \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u0627\u064b \u0645\u064f\u062a\u064e\u0642\u064e\u0628\u064e\u0651\u0644\u0627\u064b.",
      transliteration: "",
      translation: "O Allaah, I ask You for knowledge which is beneficial and sustenance which is good, and deeds which are acceptable.",
      commonName: "Supplication after the Fajr prayer",
      notes: "To be said after giving salaam for the fajr prayer.",
      repetition: "Once, after Fajr prayer",
      source: "Hisnul Muslim, Section 25, Item 73",
    ),
    OtherDua(
      id: 54,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0643\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0648\u064e\u0642\u064f\u062f\u0652\u0631\u064e\u062a\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u0650 \u0623\u064e\u062d\u0652\u064a\u0650\u0646\u0650\u064a \u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u062e\u064e\u064a\u0652\u0631\u0627\u064b \u0644\u0650\u064a \u0648\u064e\u062a\u064e\u0648\u064e\u0641\u064e\u0651\u0646\u0650\u064a \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e \u0627\u0644\u0652\u0648\u064e\u0641\u064e\u0627\u0629\u064e \u062e\u064e\u064a\u0652\u0631\u0627\u064b \u0644\u0650\u064a\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u062e\u064e\u0634\u0652\u064a\u064e\u062a\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u064e\u0651\u0647\u064e\u0627\u062f\u064e\u0629\u0650\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0650\u0651 \u0641\u0650\u064a \u0627\u0644\u0631\u0650\u0651\u0636\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u063a\u064e\u0636\u064e\u0628\u0650\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0642\u064e\u0635\u0652\u062f\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u0650\u0646\u064e\u0649 \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0642\u0652\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0646\u064e\u0639\u0650\u064a\u0645\u0627\u064b \u0644\u0627\u064e \u064a\u064e\u0646\u0652\u0641\u064e\u062f\u064f\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0642\u064f\u0631\u064e\u0651\u0629\u064e \u0639\u064e\u064a\u0652\u0646\u064d \u0644\u0627\u064e \u062a\u064e\u0646\u0652\u0642\u064e\u0637\u0650\u0639\u064f\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0631\u0650\u0651\u0636\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u0642\u064e\u0636\u064e\u0627\u0621\u0650\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0628\u064e\u0631\u0652\u062f\u064e \u0627\u0644\u0652\u0639\u064e\u064a\u0652\u0634\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0644\u064e\u0630\u064e\u0651\u0629\u064e \u0627\u0644\u0646\u064e\u0651\u0638\u064e\u0631\u0650 \u0625\u0650\u0644\u064e\u0649 \u0648\u064e\u062c\u0652\u0647\u0650\u0643\u064e \u0648\u064e\u0627\u0644\u0634\u064e\u0651\u0648\u0652\u0642\u064e \u0625\u0650\u0644\u064e\u0649 \u0644\u0650\u0642\u064e\u0627\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u063a\u064e\u064a\u0652\u0631\u0650 \u0636\u064e\u0631\u064e\u0651\u0627\u0621\u064e \u0645\u064f\u0636\u0650\u0631\u064e\u0651\u0629\u064d \u0648\u064e\u0644\u0627\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064d \u0645\u064f\u0636\u0650\u0644\u064e\u0651\u0629\u064d\u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0632\u064e\u064a\u0650\u0651\u0646\u064e\u0651\u0627 \u0628\u0650\u0632\u0650\u064a\u0646\u064e\u0629\u0650 \u0627\u0644\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0647\u064f\u062f\u064e\u0627\u0629\u064b \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e.",
      transliteration: "",
      translation: "O Allaah, by Your knowledge of the unseen and Your power over creation, keep me alive so long as You know such life to be good for me and take me if You know death to be better for me. O Allaah, make me fearful of You whether in secret or in public and I ask You to make me true in speech, in times of pleasure and anger. I ask you to make me moderate in times of wealth and poverty and I ask You for everlasting bliss and joy which will never cease. I ask You to make me pleased with what You have decreed and for an easy life after death. I ask You for the sweetness of looking upon Your Face and a longing to encounter You in a manner which does not entail a calamity which will bring about harm nor a trial which will cause deviation. O Allaah, beautify us with the adornment of faith and make us of those who guide and are rightly guided.",
      commonName: "Supplication after the last tashahhud and before salaam (8)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 62",
    ),
    OtherDua(
      id: 55,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u064a\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0628\u0650\u0623\u064e\u0646\u064e\u0651\u0643\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0623\u064e\u062d\u064e\u062f\u064f \u0627\u0644\u0635\u064e\u0651\u0645\u064e\u062f\u064f \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0643\u064f\u0641\u064f\u0648\u0627\u064b \u0623\u064e\u062d\u064e\u062f\u064c \u0623\u064e\u0646\u0652 \u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u0650\u064a \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u064a \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u064e\u0651\u062d\u0650\u064a\u0645\u064f.",
      transliteration: "",
      translation: "O Allaah, I ask You O Allaah, as You are -The One, The Only, As-Samad, The One who begets not, nor was He begotten and there is none like unto Him- that You forgive me my sins for verily You are The Oft-Forgiving, Most-Merciful.",
      commonName: "Supplication after the last tashahhud and before salaam (9)",
      notes: "As-Samad: The Self-Sufficient Master, Possessor of perfect attributes whom all of creation turn to in all their needs.",
