    OtherDua(
      id: 56,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u064e\u0651 \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u062d\u0652\u062f\u064e\u0643\u064e \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u0645\u064e\u0646\u064e\u0651\u0627\u0646\u064f \u064a\u064e\u0627 \u0628\u064e\u062f\u0650\u064a\u0639\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u0627\u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0644\u0627\u064e\u0644\u0650 \u0648\u064e\u0627\u0644\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650 \u064a\u064e\u0627\u062d\u064e\u064a\u064f\u0651 \u064a\u064e\u0627\u0642\u064e\u064a\u064f\u0651\u0648\u0645\u064f \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064e \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650.",
      transliteration: "",
      translation: "O Allaah, I ask You as unto You is all praise, none has the right to be worshipped except You, alone, without partner. You are the Benefactor. O Originator of the heavens and the Earth, O Possessor of majesty and honour, O Ever Living, O Self-Subsisting and Supporter of all, verily I ask You for Paradise and I take refuge with You from the Fire.",
      commonName: "Supplication after the last tashahhud and before salaam (10)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 64",
    ),
    OtherDua(
      id: 57,
      arabicOnly: "\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0650\u0651\u064a \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u064e\u0651\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0623\u064e\u062d\u064e\u062f\u064f \u0627\u0644\u0635\u064e\u0651\u0645\u064e\u062f\u064f \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0643\u064f\u0641\u064f\u0648\u0627\u064b \u0623\u064e\u062d\u064e\u062f\u064c.",
      transliteration: "",
      translation: "O Allaah, I ask You, as I bear witness that You are Allaah, none has the right to be worshipped except You, The One, As-Samad Who begets not nor was He begotten and there is none like unto Him.",
      commonName: "Supplication after the last tashahhud and before salaam (11)",
      notes: "",
      repetition: "Once, after the last tashahhud, before salaam",
      source: "Hisnul Muslim, Section 24, Item 65",
    ),
    OtherDua(
      id: 58,
      arabicOnly: "\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e. (\u062b\u0644\u0627\u062b\u0627\u064b) \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u064a\u064e\u0627\u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0644\u0627\u064e\u0644\u0650 \u0648\u064e\u0627\u0644\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650.",
      transliteration: "",
      translation: "I ask Allaah for forgiveness. (three times) O Allaah, You are As-Salaam and from You is all peace, Blessed are You, O Possessor of majesty and honour.",
      commonName: "Remembrance after salaam (1)",
      notes: "As-Salaam: The One Who is free from all defects and deficiencies.",
